/// <summary>普通测试配置不能启用本轮正式文件时间验收。</summary>
public sealed class FileCalendarNativeFactAttribute:FactAttribute
{
    public FileCalendarNativeFactAttribute(){if(!File.Exists(Environment.GetEnvironmentVariable("METARILL_FILE_CALENDAR_NATIVE_SETTINGS")))Skip="缺专属批准租约，真实文件时间/账号窗口/MySQL验收未执行。";}
}

