            stage="原旧图片上传与公开读取";var png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAIAAAADCAYAAAC56t6BAAAAEUlEQVR4nGP4z8DwH4QZMBgAoXkL9U3EmgcAAAAASUVORK5CYII=");using(var form=new MultipartFormDataContent()){form.Add(new ByteArrayContent(png),"file","calendar-legacy.png");var response=await Send(HttpMethod.Post,"/api/admin/sys/upload/uploadImage",form);var url=response.GetProperty("location").GetString()!;Assert.StartsWith("/api/admin/sys/file-library/public-content/",url);Assert.Equal(url,response.GetProperty("data").GetProperty("url").GetString());using var anonymous=new HttpClient{BaseAddress=host.Client.BaseAddress};using var read=await anonymous.GetAsync(url);Assert.Equal(HttpStatusCode.OK,read.StatusCode);Assert.Equal(png[..8],(await read.Content.ReadAsByteArrayAsync())[..8]);}
            stage="真实生成CRUD、引用与回滚";before=DateTimeOffset.UtcNow;var customer=(await Send(HttpMethod.Post,"/api/admin/auto/sample_customer/81001/add",new{name="file-calendar-customer"})).GetProperty("data").GetProperty("id").ToString();var created=await Send(HttpMethod.Post,Contract+"add",new{name="file-calendar-record",sampleCustomerId=customer,amount=10,attachments=new[]{current.ToString(CultureInfo.InvariantCulture)}});var record=long.Parse(created.GetProperty("data").GetProperty("id").ToString(),CultureInfo.InvariantCulture);var original=Assert.Single(await store.ReadAsync("sample_contract",Row("id",record)));Calendar(original["insert_time"],before,1);var originalInsert=original["insert_time"];before=DateTimeOffset.UtcNow;await Send(HttpMethod.Post,Contract+"update",new{id=record.ToString(CultureInfo.InvariantCulture),name="omitted-files-keep"});var updated=Assert.Single(await store.ReadAsync("sample_contract",Row("id",record)));Assert.Equal(originalInsert,updated["insert_time"]);Calendar(updated["update_time"],before,1);Assert.Single(await fileStore.ReadAsync("yz_file_ref",Row("record_id",record)));var snapshot=JsonSerializer.Serialize(updated);
