            var existing=(await store.ReadIncludingDeletedAsync("sample_contract")).Select(row=>SqlRowStore.Id(row)).ToHashSet();before=DateTimeOffset.UtcNow;await Send(HttpMethod.Post,Contract+"copy/"+record);var copiedRow=Assert.Single(await store.ReadAsync("sample_contract"),row=>!existing.Contains(SqlRowStore.Id(row)));var copyId=SqlRowStore.Id(copiedRow);Calendar(copiedRow["insert_time"],before,1);Calendar(copiedRow["update_time"],before,1);Assert.Single(await fileStore.ReadAsync("yz_file_ref",Row("record_id",copyId)));before=DateTimeOffset.UtcNow;await Send(HttpMethod.Delete,Contract,new{id=copyId.ToString(CultureInfo.InvariantCulture)});Calendar(Assert.Single(await store.ReadIncludingDeletedAsync("sample_contract",Row("id",copyId)))["delete_no"],before,1);Assert.Empty(await fileStore.ReadAsync("yz_file_ref",Row("record_id",copyId)));Calendar(Assert.Single(await fileStore.ReadIncludingDeletedAsync("yz_file_ref",Row("record_id",copyId)))["delete_no"],before);
            stage="真实账号日历窗口和UTC会话";foreach(var fieldName in new[]{"validity_time","login_stop_time","login_rise_time"})
