        Task Receipt(string name,object value)=>File.WriteAllTextAsync(Path.Combine(evidence,name+".json"),JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true})+"\n");
        async Task<MetadataCatalog> Model(string name)=>JsonSerializer.Deserialize<MetadataCatalog>(await File.ReadAllTextAsync(CSharpGenerator.SafePath(copied.PackageRoot,"backend/metadata/"+name+".json")),new JsonSerializerOptions(JsonSerializerDefaults.Web))!;
        Task<JsonElement> Send(HttpMethod method,string route,object? body=null,HttpStatusCode expected=HttpStatusCode.OK)=>FreshWebHttp.SendAsync(host!.Client,method,route,body,expected);
        async Task<string> Run(ProcessStartInfo info,string name)=>await RunOwned(info,evidence,name,options.ConnectionString,password);
        async Task<Dictionary<string,object?>> FileRow(long id)=>Assert.Single(await fileStore.ReadIncludingDeletedAsync("yz_file_library",Row("id",id)));
        async Task<long> Plan(string name)
        {
            var response=await Send(HttpMethod.Post,Files+"upload-plan",new{originalName=name,mimeType="text/html",sizeBytes=content.Length,configColumnId=field,sha256=Convert.ToHexStringLower(SHA256.HashData(content))});var data=response.GetProperty("data");var id=long.Parse(data.GetProperty("fileId").ToString(),CultureInfo.InvariantCulture);var plan=data.GetProperty("plan");Assert.Equal("local",plan.GetProperty("providerCode").GetString());Assert.Equal("SERVER_MULTIPART",plan.GetProperty("uploadMode").GetString());var expires=plan.GetProperty("expireAt").GetDateTimeOffset();Assert.Equal(TimeSpan.Zero,expires.Offset);Assert.Equal(expires.UtcDateTime.Ticks,Convert.ToDateTime((await FileRow(id))[FileUploadLifetime.DeadlineColumn],CultureInfo.InvariantCulture).Ticks);return id;
        }
        async Task Upload(long id,string name,bool allowed)
        {
            var count=Directory.Exists(filesRoot)?Directory.GetFiles(filesRoot,"*",SearchOption.AllDirectories).Length:0;using var form=new MultipartFormDataContent();form.Add(new ByteArrayContent(content),"file",name);var result=await Send(HttpMethod.Post,Files+"local-upload/"+id,form,allowed?HttpStatusCode.OK:HttpStatusCode.InternalServerError);
            if(!allowed){Assert.Equal("操作失败，请由应用管理员核查服务端状态。",result.GetProperty("msg").GetString());Assert.Equal(count,Directory.Exists(filesRoot)?Directory.GetFiles(filesRoot,"*",SearchOption.AllDirectories).Length:0);return;}
            Assert.Equal("uploaded",result.GetProperty("data").GetProperty("status").GetString());var descriptor=(await Send(HttpMethod.Post,Files+"complete",new{fileId=id.ToString(CultureInfo.InvariantCulture)})).GetProperty("data");Assert.Equal("ready",descriptor.GetProperty("status").GetString());Assert.Equal("text/plain",descriptor.GetProperty("mimeType").GetString());using var read=await host!.Client.GetAsync(Files+"protected-content/"+id);Assert.Equal(HttpStatusCode.OK,read.StatusCode);Assert.Equal(content,await read.Content.ReadAsByteArrayAsync());
        }
