    /// <summary>本轮固定日历为UTC+8；DB读回值不能再附加Kind偏移，零精度业务列允许一秒舍入。</summary>
    private static DateTime CalendarNow()=>DateTime.SpecifyKind(DateTimeOffset.UtcNow.UtcDateTime.AddHours(8),DateTimeKind.Unspecified);
    private static void Calendar(object? value,DateTimeOffset before,int roundingSeconds=0){var actual=Assert.IsType<DateTime>(value);Assert.InRange(actual,before.UtcDateTime.AddHours(8).AddSeconds(-roundingSeconds).AddMilliseconds(-2),CalendarNow().AddSeconds(roundingSeconds).AddMilliseconds(2));}
    /// <summary>合成记录只进入本轮独占库，不将客户端项目选择当成真实授权。</summary>
    private static Dictionary<string,object?> Row(params object?[] values){var result=new Dictionary<string,object?>();for(var i=0;i<values.Length;i+=2)result[(string)values[i]!]=values[i+1];return result;}
    /// <summary>在任何DDL前读实例及真实登录主体，固定随机库和受限临时账号。</summary>
    private static async Task Pin(DatabaseSession session,JsonElement pin)
    {
        await using var connection=session.Provider.CreateConnection(session.Options);await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText="SELECT DATABASE(),@@hostname,@@server_uuid,CURRENT_USER()";await using var reader=await command.ExecuteReaderAsync();Assert.True(await reader.ReadAsync());Assert.Equal(session.Options.ExpectedDatabase,reader.GetString(0));Assert.Equal(pin.GetProperty("expectedHostname").GetString(),reader.GetString(1));Assert.Equal(pin.GetProperty("expectedServerUuid").GetString(),reader.GetString(2));Assert.StartsWith(new MySqlConnector.MySqlConnectionStringBuilder(session.Options.ConnectionString).UserID+"@",reader.GetString(3));
    }
    /// <summary>只执行编译期固定只读计数；不读取SQL正文或其它数据库行。</summary>
    private static async Task<long> Scalar(DatabaseSession session,string sql){await using var connection=session.Provider.CreateConnection(session.Options);await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=sql;return Convert.ToInt64(await command.ExecuteScalarAsync(),CultureInfo.InvariantCulture);}
    /// <summary>只拥有本次命令进程；脱敏后落盘，超时结束自己创建的进程树且不自动重试。</summary>
    private static async Task<string> RunOwned(ProcessStartInfo info,string evidence,string name,params string[] secrets)
    {
        using var process=Process.Start(info)!;var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(3));var timedOut=false;try{await process.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){timedOut=true;if(!process.HasExited)process.Kill(true);await process.WaitForExitAsync();}var text=await stdout;var error=await stderr;var builder=new MySqlConnector.MySqlConnectionStringBuilder(info.Environment["Database__ConnectionString"]??throw new InvalidOperationException("命令缺少本轮测试连接。"));foreach(var secret in secrets.Append(builder.Password).Where(value=>!string.IsNullOrEmpty(value)).OrderByDescending(value=>value.Length)){text=text.Replace(secret,"[已脱敏]",StringComparison.Ordinal);error=error.Replace(secret,"[已脱敏]",StringComparison.Ordinal);}await File.WriteAllTextAsync(Path.Combine(evidence,name+".log"),text+"\n"+error);if(timedOut)throw new TimeoutException("正式文件时间命令超时，脱敏证据已保留。");Assert.True(process.ExitCode==0,"正式文件时间命令失败，详见私有脱敏日志。");return text;
    }
